import fs from 'node:fs';import assert from 'node:assert/strict';
const file=process.argv[2]||'cong_el_calafate_android/app/src/main/assets/app.js',src=fs.readFileSync(file,'utf8');
const start=src.indexOf('function cecV175Straighten(points){'),end=src.indexOf('function commitStroke(points){',start);
assert(start>=0&&end>start,'Geometría V1.7.5 no incorporada');
const text=src.slice(start,end);
const make=new Function('$',text+';return {line:cecV175Straighten,trace:cecV175TraceSample};');
const g=make(()=>({getBoundingClientRect(){return{width:350,height:520}}}));
const casi=(a,b,eps)=>Math.abs(a-b)<=eps;
const horizontal=Array.from({length:70},(_,i)=>({x:10+i*.75,y:30+Math.sin(i/3)*.28}));
const straight=g.line(horizontal);
assert(straight.length===2,'La línea debe tener 2 extremos');
assert(casi(straight[0].y,straight[1].y,.05),'Línea horizontal con ruido debe alinearse');
assert(Math.abs(straight[1].x-straight[0].x)>35,'Conservar longitud');
const diag=Array.from({length:65},(_,i)=>({x:12+i*.7,y:19+i*.48+Math.sin(i/2)*.17}));
const d=g.line(diag);
assert(d.length===2&&Math.abs(d[1].y-d[0].y)>20,'No horizontalizar calles diagonales');
assert(Math.abs(d[1].x-d[0].x)>30,'Conservar dirección de calle');
assert(g.trace(Array.from({length:200},(_,i)=>({x:i/2,y:i/3}))).length<=48,'Limitar memoria de gestos');
assert(src.includes('tracePoints:cecV175TraceSample(points)'),'Conservar muestras para inferencia mapa-lista');
assert(src.includes('const samples=st.tracePoints||st.points'),'Reconocimiento debe usar trazado real, no línea rectificada');
assert(src.includes('now-lastRefresh<180000'),'Limitar llamadas CSV redundantes a cada apertura');
console.log('V1.7.5 pruebas correctas: horizontal, diagonal, gestos muestreados, reconocimiento y refresco CSV');